import java.io.*;
import java.util.Arrays;

/**
 * Created by dalt on 2018/3/14.
 */
public class CF939F_Variant2 {
    public static final int INF = (int) 1e8;
    public static BufferedReader br;
    public static PrintStream ps;

    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        ps = System.out;

        execute();

        ps.flush();
    }

    public static void execute() throws IOException {
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int k = Integer.parseInt(firstLine[1]);

        int[][] intervals = new int[k + 2][2];
        for (int i = 1; i <= k; i++) {
            String[] parts = br.readLine().split(" ");
            intervals[i][0] = Integer.parseInt(parts[0]);
            intervals[i][1] = Integer.parseInt(parts[1]);
        }
        intervals[k + 1][0] = 2 * n;
        intervals[k + 1][1] = 2 * n;

        k++;

        Node[] dpStates = new Node[2];
        dpStates[0] = Node.build(0, n);
        dpStates[1] = Node.build(0, n);

        int[] tempData = new int[n + 1];

        for (int i = 1; i <= k; i++) {
            Node current = dpStates[i & 1];
            Node previous = dpStates[(i - 1) & 1];

            int[] interval = intervals[i];
            int intervalLen = interval[1] - interval[0];
            int middleLen = interval[0] - intervals[i - 1][1];

            Node.toArray(0, n, tempData, previous);
            System.arraycopy(tempData, 0, tempData, Math.min(tempData.length, intervalLen + middleLen), Math.max(0, n + 1 - (intervalLen + middleLen)));
            Arrays.fill(tempData, 0, Math.min(tempData.length, intervalLen + middleLen), INF);

            int minX = interval[1] - middleLen - intervalLen;
            int maxX = interval[1] - middleLen;
            for (int j = 0; j <= n; j++) {
                int needTime = Node.query(minX - j, maxX - j, 0, n, previous);
                tempData[j] = Math.min(tempData[j], needTime + 1);
            }

            for (int j = 0; j <= n; j++) {
                int needTime = Node.query(j - middleLen - intervalLen, j - middleLen, 0, n, previous);
                tempData[j] = Math.min(tempData[j], needTime + 2);
            }

            Node.fromArray(0, n, tempData, current);
        }

        int result = Node.query(n, n, 0, n, dpStates[k & 1]);
        if (result < INF) {
            ps.println("Full");
            ps.println(result);
        } else {
            ps.println("Hungry");
        }
    }

    static class Node {
        Node left, right;
        int min;
        boolean dirty;
        int batchSet;

        public static void setRange(int f, int t, int l, int r, int val, Node node) {
            if (f > r || t < l) return;
            if (f <= l && t >= r) {
                node.setVal(val);
                return;
            }
            node.pushDown();
            int m = (l + r) >> 1;
            setRange(f, t, l, m, val, node.left);
            setRange(f, t, m + 1, r, val, node.right);
            node.update();
        }

        public static Node create(int l, int r) {
            Node node = new Node();
            if (l != r) {
                int m = (l + r) >> 1;
                node.left = create(l, m);
                node.right = create(m + 1, r);
            }
            node.min = INF;
            return node;
        }

        public static int queryRange(int f, int t, int l, int r, Node node) {
            if (f > r || t < l) return INF;
            if (f <= l && r <= t) return node.min;
            node.pushDown();
            int m = (l + r) >> 1;
            return Math.min(queryRange(f, t, l, m, node.left), queryRange(f, t, m + 1, r, node.right));
        }

        public static void fillFromArray(int l, int r, int[] data, Node node) {
            if (l == r) {
                node.min = data[l];
                return;
            }
            int m = (l + r) >> 1;
            fillFromArray(l, m, data, node.left);
            fillFromArray(m + 1, r, data, node.right);
            node.update();
        }

        public static void fillToArray(int l, int r, int[] data, Node node) {
            if (l == r) {
                data[l] = node.min;
                return;
            }
            node.pushDown();
            int m = (l + r) >> 1;
            fillToArray(l, m, data, node.left);
            fillToArray(m + 1, r, data, node.right);
        }

        public void update() {
            this.min = Math.min(left.min, right.min);
        }

        public void setVal(int val) {
            this.min = val;
            this.batchSet = val;
            this.dirty = true;
        }

        public void pushDown() {
            if (dirty) {
                left.setVal(batchSet);
                right.setVal(batchSet);
                dirty = false;
            }
        }
    }
}
